--In theory the below shouldt be needed once the FAF-Develop changes are integrated into FAF (expected June 2023), although probably no harm leaving for backwards compatibility
--Commented out for v24 due to compatibility concerns following new approach (where need to wait until after OnCreateAI before generating map)

local AiBotEvents = import('/lua/AiBot/AI/AiBotEvents.lua')
local AiBotUtilities = import('/lua/AiBot/AI/AiBotUtilities.lua')
local AiBotConditions = import('/lua/AiBot/AI/AiBotConditions.lua')
local AiBotOverseer = import('/lua/AiBot/AI/AiBotOverseer.lua')

local StandardBrain = import("/lua/aibrain.lua").AIBrain
local AiBotOldAIBrain = AIBrain
AIBrain = Class(AiBotOldAIBrain) {



    OnCreateAI = function(self, planName)
        LOG('OnCreateAI for campaign is running for brain '..(self.Nickname or 'nil')..'; ScenarioInfo.type (i.e. is this skirmish or campaign)='..(ScenarioInfo.type or 'nil'))
        --Delalyed check of if should apply AiBot logic to the brain
        self.CampaignAI = true
        AiBotOverseer.iTimeOfLatestBrainToCheckForAiBotLogic = GetGameTimeSeconds()
        ForkThread(AiBotOverseer.DecideWhetherToApplyAiBotToCampaignAI, self, planName)

        AiBotOldAIBrain.OnCreateAI(self, planName)


    end,

    OnBeginSession = function(self)
        StandardBrain.OnBeginSession(self)
        import('/lua/AiBot/AI/AiBotOverseer.lua').bBeginSessionTriggered = true
        if not(self.AiBotAI) then
            -- requires navigational mesh (forked earlier by AiBotBrainCreated;
            -- just wait for it here rather than blocking the sim)
            while not(AiBotUtilities.NavUtils.IsGenerated()) do
                WaitTicks(1)
            end
            --import("/lua/sim/NavUtils.lua").Generate()

            -- requires these datastructures to understand the game
            --Jip note 2023-10-28 - these dont need to be loaded if I'm not using them (i.e. if not referencing any of the below in code)
            --[[self.GridReclaim = import("/lua/ai/gridreclaim.lua").Setup(self)
            self.GridBrain = import("/lua/ai/gridbrain.lua").Setup()
            self.GridRecon = import("/lua/ai/gridrecon.lua").Setup(self)
            self.GridPresence = import("/lua/AI/GridPresence.lua").Setup(self)--]]
        end
    end,

}

